# ## SOLUTION

**Root cause (BUG-024):** the E2E suite asserted HTTP-status smoke semantics, so `SSESyncProvider` — which skipped its `EventSource` entirely and answered every `pushUpdate` with `console.log('coming soon')` — stayed green for 60+ ticks. The stubs also targeted a **non-existent global `/api/v1/events`** while the backend already exposed the real **tree-scoped** `/trees/{tree_id}/events` (SSE) and `/trees/{tree_id}/sync` endpoints. The fix is to delete the stubs, wire the real endpoints on both sides, and add tests that assert **real data flow** (two-context convergence), not status codes.

### 1. Backend (Go) — wire the sync ingest + broadcast path

`POST /trees/{tree_id}/sync` handler decodes the base64 `yjs_update`, applies it via the engine, and returns the fresh state vector. `GET /trees/{tree_id}/events` streams `yjs_update` events to every subscriber of that tree, with `Last-Event-ID` replay so reconnects don't drop updates.

```go
// internal/api/sync.go
type PushUpdateRequest struct {
    YjsUpdate string `json:"yjs_update"` // base64-encoded Yjs binary update
    ClientID  string `json:"client_id"`
}
type PushUpdateResponse struct {
    TreeID      string `json:"tree_id"`
    StateVector string `json:"state_vector"` // base64, so clients can diff/sync
}

// HandlePushUpdate: the REAL sync ingest (stub logged "coming soon").
func (s *Server) HandlePushUpdate(w http.ResponseWriter, r *http.Request) {
    treeID := r.PathValue("tree_id")
    if treeID == "" { http.Error(w, "missing tree_id", http.StatusBadRequest); return }

    var req PushUpdateRequest
    if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 8<<20)).Decode(&req); err != nil {
        http.Error(w, "invalid json body: "+err.Error(), http.StatusBadRequest); return
    }
    if req.YjsUpdate == "" { http.Error(w, "missing yjs_update", http.StatusBadRequest); return }

    raw, err := base64.StdEncoding.DecodeString(req.YjsUpdate)
    if err != nil { http.Error(w, "yjs_update is not valid base64", http.StatusBadRequest); return }

    sv, err := s.engine.ApplyYjsUpdate(r.Context(), treeID, raw, req.ClientID)
    if err != nil {
        if errors.Is(err, engine.ErrTreeNotFound) { http.Error(w, "tree not found", http.StatusNotFound); return }
        if errors.Is(err, engine.ErrInvalidUpdate) { http.Error(w, "invalid yjs update payload", http.StatusBadRequest); return }
        slog.Error("apply yjs update", "tree_id", treeID, "err", err)
        http.Error(w, "internal error", http.StatusInternalServerError); return
    }
    writeJSON(w, http.StatusOK, PushUpdateResponse{TreeID: treeID,
        StateVector: base64.StdEncoding.EncodeToString(sv)})
}
```

```go
// internal/engine/yjs.go
var (
    ErrTreeNotFound  = errors.New("tree not found")
    ErrInvalidUpdate = errors.New("invalid yjs update")
)

// ApplyYjsUpdate merges the update into the tree's authoritative doc
// (Yjs updates are content-addressed, so duplicate/out-of-order applies
// are idempotent), bumps the per-tree sequence, and broadcasts the raw
// update to all SSE subscribers of that tree.
func (e *Engine) ApplyYjsUpdate(ctx context.Context, treeID string, update []byte, clientID string) ([]byte, error) {
    e.mu.RLock(); td, ok := e.trees[treeID]; e.mu.RUnlock()
    if !ok { return nil, fmt.Errorf("%w: %s", ErrTreeNotFound, treeID) }

    td.mu.Lock(); defer td.mu.Unlock() // serialize per tree: no interleaved partial updates
    if err := td.doc.ApplyUpdate(update); err != nil {
        return nil, fmt.Errorf("%w: %v", ErrInvalidUpdate, err) // garbage bytes -> 400
    }
    td.seq++
    e.broker.Broadcast(treeID, Event{Type: "yjs_update", TreeID: treeID, Seq: td.seq,
        Payload: base64.StdEncoding.EncodeToString(update)})
    return td.doc.StateVector(), nil
}
