### 2. Frontend (TS) — real `EventSource` + binary push + snake_case→Yjs mapping

```ts
// src/sync/SSESyncProvider.ts  (replaces the stub that skipped EventSource
// and logged 'coming soon' in pushUpdate)
interface ServerEvent {
  type: 'yjs_update' | 'state_vector' | 'heartbeat';
  tree_id: string;   // snake_case on the wire
  seq: number;
  yjs_update?: string; // base64
}

export class SSESyncProvider {
  private es: EventSource | null = null;
  private reconnectDelay = 1000;
  private readonly maxReconnectDelay = 15000;

  constructor(private readonly cfg: { baseUrl: string; treeId: string }) {}

  connect(): void {
    if (this.es) return;
    // tree-scoped REAL endpoint — NOT the phantom global /api/v1/events
    this.es = new EventSource(
      `${this.cfg.baseUrl}/trees/${encodeURIComponent(this.cfg.treeId)}/events`,
      { withCredentials: true }, // carry session cookie so auth'd SSE works
    );
    this.es.addEventListener('yjs_update', (e) => this.onYjsUpdate(e));
    this.es.onopen  = () => { this.reconnectDelay = 1000; };
    this.es.onerror = () => { /* exponential backoff reconnect; Last-Event-ID is sent automatically */ };
  }

  // snake_case → Yjs payload mapping (this was entirely missing)
  private onYjsUpdate(e: MessageEvent): void {
    const ev = JSON.parse(e.data) as ServerEvent;
    const b64 = ev.yjs_update ?? ev.payload;
    if (!b64) return;
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    this.emit('remote-update', bytes, ev.seq);
  }

  // binary fetch push — no more 'coming soon'
  async pushUpdate(update: Uint8Array, clientId: string): Promise<Uint8Array> {
    const resp = await fetch(
      `${this.cfg.baseUrl}/trees/${encodeURIComponent(this.cfg.treeId)}/sync`,
      { method: 'POST', headers: { 'Content-Type': 'application/octet-stream', 'X-Client-Id': clientId },
        body: update, credentials: 'same-origin' },
    );
    if (!resp.ok) throw new Error(`sync push failed: HTTP ${resp.status}`);
    return new Uint8Array(await resp.arrayBuffer()); // state_vector ack
  }
}
```

```ts
// src/sync/YjsTree.ts — glue: local edits encode + push; remote updates apply
export class YjsTree {
  readonly doc = new Y.Doc();
  constructor(private readonly provider: SSESyncProvider, private readonly clientId: string) {
    provider.on('remote-update', (u: Uint8Array) => Y.applyUpdate(this.doc, u, 'remote'));
  }
  localEdit() {
    const update = Y.encodeStateAsUpdate(this.doc);
    void this.provider.pushUpdate(update, this.clientId); // real wire, real endpoint
  }
}
```

